const bytesToBase64 = (bytes) => { let binary=''; for(let i=0;i<bytes.length;i+=0x8000) binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000)); return btoa(binary); };
const base64ToBytes = (value) => Uint8Array.from(atob(value), c=>c.charCodeAt(0));
const deriveBackupKey = async (passphrase,salt,iterations,usages) => {
  const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);
  return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,usages);
};
